/bin/zsh -lc "python3 -c 'from heapq import heappop, heappush
edges = [(1, 2, 1), (2, 3, 1), (3, 1, 1)]
def distances(start, bidirectional):
    graph = [[] for _ in range(4)]
    for u, v, w in edges:
        graph[u].append((v, w))
        if bidirectional:
            graph[v].append((u, w))
    dist = [float(\"inf\")] * 4
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        cost, u = heappop(heap)
        if cost "'!= dist[u]:
            continue
        for v, w in graph[u]:
            if cost + w < dist[v]:
                dist[v] = cost + w
                heappush(heap, (dist[v], v))
    return dist[1:]
for bidirectional in [False, True]:
    all_dist = [distances(s, bidirectional) for s in range(1, 4)]
    print({"interpretation": "undirected" if bidirectional else "u_to_v", "all_pairs_reachable": all(d < float("inf") for row in all_dist for d in row), "published_sample_answer": all_dist[0][1], "counterexample_answer_for_s_1_t_3": all_dist[0][2]})'"'"

